import { ProblemCode } from './generated/model';

/** A translation key plus the ICU parameters of its message. */
export interface ErrorMessage {
  key: string;
  params: Record<string, string | number>;
}

/** What a failed request gives us; Angular's HttpErrorResponse has exactly these two. */
export interface HttpFailure {
  /** 0 = no answer at all (offline, DNS, CORS). */
  status: number;
  /** The response body: Problem Details from our API, or anything a proxy sends. */
  error: unknown;
}

/** Codes of the contract, as generated by Orval — a code the client does not know is not here. */
const KNOWN_CODES: ReadonlySet<string> = new Set(Object.values(ProblemCode));

/** Translation key of an error code (top level or one field): `errors.<code>` (ADR-0008). */
export function problemCodeKey(code: ProblemCode): string {
  return `errors.${code}`;
}

/**
 * The message for a failed request (ADR-0008):
 * - no answer → errors.generic.network;
 * - Problem Details with a code of the contract → errors.<code>;
 * - anything else (unknown code, a proxy's HTML page) → by status:
 *   5xx → errors.server.internal, 4xx → errors.generic.client.
 */
export function problemMessage(failure: HttpFailure): ErrorMessage {
  if (failure.status === 0) {
    return { key: 'errors.generic.network', params: {} };
  }
  const code =
    typeof failure.error === 'object' && failure.error !== null
      ? (failure.error as { code?: unknown }).code
      : undefined;
  if (typeof code === 'string' && KNOWN_CODES.has(code)) {
    return { key: problemCodeKey(code as ProblemCode), params: {} };
  }
  return {
    key:
      failure.status >= 500
        ? 'errors.server.internal'
        : 'errors.generic.client',
    params: {},
  };
}
